for(let i=1;i<=4;i++){const section=document.createElement('div');section.style.cssText='padding:12px 0;border-bottom:1px solid #eef1f5';const heading=document.createElement('strong');heading.textContent='項次 '+i;section.append(heading);for(const [key,labelText] of [['project','本年度負責之工作與專案名稱'],['outcome','達成狀況與具體成果']]){const id=key+i;const label=document.createElement('label');label.htmlFor=id;label.textContent=labelText;const area=document.createElement('textarea');area.id=id;section.append(label,area);fields.push(id)}projectRows.append(section)}
