const supervisorRubrics=[{"name": "組織領導成果", "sourceName": "組導織成領果", "desc": "指運用管理能力統轄部屬，包括工作的分配、教導與啟發所做努力的程度。", "criteria": ["管理良好，領導有方獲得全體部屬之心服，組織內士氣高昂、規律好。", "管理熱心，部屬心服、士氣高昂、規律好。", "管理認真，組織內士氣、規律尚稱良好。", "對管理不太關心，組織內士氣稍差，部屬有違規現象。", "管理懈怠、引起部屬不滿，組織散漫、士氣低落、規律差。"], "levels": [[18.0, 19.0, 20.0], [15.0, 16.0, 17.0], [12.0, 13.0, 14.0], [9.0, 10.0, 11.0], [6.0, 7.0, 8.0]]}, {"name": "業務處理成果", "sourceName": "業理務成處果", "desc": "指所完成業務工作成果的正確性與可靠性之程度。", "criteria": ["實事求是，適切適時行事且能貫徹到底，成果極佳，能充分信賴。", "工作細心，適時行事，成果正確，堪能信賴。", "工作細心且能在預定時間內完成，成果尚稱良好。", "工作不夠細心，常有錯誤，成果稍差，須加催促。", "工作能力極弱，成果差，浪費多，須嚴加督導。"], "levels": [[13.0, 14.0, 15.0], [10.0, 11.0, 12.0], [7.0, 8.0, 9.0], [5.5, 6.0, 6.5], [4.0, 4.5, 5.0]]}, {"name": "革新改進績效", "sourceName": "革進新績改效", "desc": "指為達成工作目標或解決工作問題所做創造、思考及革新之績效程度。", "criteria": ["具有敏感的問題意識，積極謀求革新，著有成效。", "自動改進工作方法或提出建議，力求革新、提高效率，成效良好。", "能擬定工作改善方法或提出建議，成效普通。", "問題意識稍差，份內工作少有改進。", "滿足現狀、不謀改進、工作效率差。"], "levels": [[13.0, 14.0, 15.0], [10.0, 11.0, 12.0], [7.0, 8.0, 9.0], [5.5, 6.0, 6.5], [4.0, 4.5, 5.0]]}, {"name": "接洽表現情形", "sourceName": "接現洽情表形", "desc": "指內外接洽或商討事項所表現才能及風度。", "criteria": ["任何場合皆能貫徹正確主張，令人感服，圓滿達成目的。", "任何商討或接洽，都有正確主張，能達成目的。", "接拾或商討能力及風度均為一般水準，尚能達成目的。", "無主見亦不主張，接洽能力不足，需要他人協助。", "對答技巧差，態度欠溫和，給對方留不好的印象。"], "levels": [[9.0, 9.5, 10.0], [7.5, 8.0, 8.5], [6.0, 6.5, 7.0], [4.5, 5.0, 5.5], [3.0, 3.5, 4.0]]}, {"name": "盡責努力程度", "sourceName": "\\盡力責程努度", "desc": "指完成業務職掌及承上啟下之努力程度。", "criteria": ["有強烈責任感，認真執行業務，任勞任怨完成工作。", "富有責任感，認識本身職責，認真執行業務。", "有責任感，執行業務努力程度尚稱良好。", "責任感稍差，時常有逃避責任的傾向。", "無責任感，常虛報或逃避責任，轉達命令不夠徹底。"], "levels": [[9.0, 9.5, 10.0], [7.5, 8.0, 8.5], [6.0, 6.5, 7.0], [4.5, 5.0, 5.5], [3.0, 3.5, 4.0]]}, {"name": "知識與技能", "sourceName": "知識技與能", "desc": "指完成職務所必需的基本知識、專門知識及對經營狀況的認識程度。", "criteria": ["有極豐富的學識及技能，瞭解經營狀況，能充分發揮圓滿完成。", "有豐富的學識和技能，瞭解經營狀況，足夠完成本身工作。", "知識和技能均為一般水準，尚能完成本身工作。", "知識和技能稍感不足，執行職務需詳細提示。", "知識和技能均不足，影響日常工作之進行。"], "levels": [[9.0, 9.5, 10.0], [7.5, 8.0, 8.5], [6.0, 6.5, 7.0], [4.5, 5.0, 5.5], [3.0, 3.5, 4.0]]}, {"name": "操行與品德", "sourceName": "操行品與德", "desc": "指習慣、規矩、誠實、時間觀念、經濟觀念、成本觀念、修養及禮貌等。", "criteria": ["為人公正、誠實、謙虛、待人接物與品德堪為他人之模範。", "奉公守法、操守良好、穩健、有禮貌、能受他人之尊敬。", "操守普通、態度與品行良好，能獲得他人之好感。", "操守、態度、守法觀念稍差，須加督導。", "守法觀念淡薄、態度與品行均差。"], "levels": [[9.0, 9.5, 10.0], [7.5, 8.0, 8.5], [6.0, 6.5, 7.0], [4.5, 5.0, 5.5], [3.0, 3.5, 4.0]]}, {"name": "與人協調情形", "sourceName": "與調人情協形", "desc": "指為促進工作與有關部門的聯繫或與同事協調工作或協助他人程度。", "criteria": ["積極與他單位協調，自動協助他人，人群關係極佳，圓滿完成。", "能與有關單位協調，合作精神良好，順利完成。", "協調、合作、人群關係尚可，能完成本身工作。", "協調性與人群關係稍差，不願協助他人。", "缺乏合作精神，有獨善排他人行為，影響工作進行。"], "levels": [[9.0, 9.5, 10.0], [7.5, 8.0, 8.5], [6.0, 6.5, 7.0], [4.5, 5.0, 5.5], [3.0, 3.5, 4.0]]}];
const staffRubrics=[{"name": "工作改進績效", "sourceName": "工進作績改效", "desc": "指為達工作目標或解決問題所做思考及改進績效程度。", "criteria": ["具有問題意識，對本身業務能積極改進，著有成效。", "經常提出建議，實施結果成效良好。", "能就本身工作加以改進，或提出建議尚有成效。", "缺乏問題意識，尚能接受他人的建議，而改進本身工作。", "固步自封、滿足現狀、不願改進本身工作。"], "levels": [[9.0, 9.5, 10.0], [7.5, 8.0, 8.5], [6.0, 6.5, 7.0], [4.5, 5.0, 5.5], [3.0, 3.5, 4.0]]}, {"name": "知識與技能", "sourceName": "知識技與能", "desc": "指完成職務所必需的基本知識、專門知識和技能熟練的程度。", "criteria": ["有豐富的學識和技能，順利完成本身工作。", "學識和技能尚可，足夠完成本身工作。", "知識和技能為一般水準，尚能完成本身工作。", "知識和技能稍感不足，執行職務需詳細提示。", "知識和技能均不足，日常工作不能圓滿達成。"], "levels": [[9.0, 9.5, 10.0], [7.5, 8.0, 8.5], [6.0, 6.5, 7.0], [4.5, 5.0, 5.5], [3.0, 3.5, 4.0]]}, {"name": "操行與品德", "sourceName": "操行品與德", "desc": "指其工作態度、遵守規律、時間觀念、成本觀念修養、禮貌等。", "criteria": ["工作認真、態度誠懇、操行與品德為他人之模範。", "工作認真、態度良好、穩健、有禮貌、能受他人之尊敬。", "態度、品行尚可，能獲得他人好感。", "態度、品行、守法觀念稍差，須加督導。", "守法觀念淡薄、徇私誤事，態度、品行均差。"], "levels": [[9.0, 9.5, 10.0], [7.5, 8.0, 8.5], [6.0, 6.5, 7.0], [4.5, 5.0, 5.5], [3.0, 3.5, 4.0]]}, {"name": "與人協調情形", "sourceName": "與調人情協形", "desc": "指對上司的服從與同事的協調及協助他人的程度。", "criteria": ["絕對聽從指示命令，自動與人協調，人群關係圓滑。", "聽從指示命令，與人合作，人群關係良好。", "服從性、協調性、人群關係尚稱良好。", "服從性、協調性稍差，不願協助他人，人群關係稍差。", "不聽從指示命令，我行我素，缺乏合作精神，人群關係差。"], "levels": [[9.0, 9.5, 10.0], [7.5, 8.0, 8.5], [6.0, 6.5, 7.0], [4.5, 5.0, 5.5], [3.0, 3.5, 4.0]]}, {"name": "工作意欲程度", "sourceName": "工欲作程意度", "desc": "指對工作的熱誠自動自發的精神、研究心及不怕困難的氣魄。", "criteria": ["極有工作熱誠，精益求精，經常進修，富有上進心。", "對工作具有興趣及積極性，且能認真執行，力求上進。", "圓滿達成本身工作，工作意欲尚稱良好。", "工作意欲稍差，偶而偷懶、逃避困難工作之傾向，缺乏向上心。", "意志消沈、陽奉陰違，毫無工作欲。"], "levels": [[9.0, 9.5, 10.0], [7.5, 8.0, 8.5], [6.0, 6.5, 7.0], [4.5, 5.0, 5.5], [3.0, 3.5, 4.0]]}, {"name": "貫徹命令程度", "sourceName": "貫令徹程命度", "desc": "指完成工作責任及貫徹指示命令的努力程度。", "criteria": ["強烈責任感，認識本身工作的重要性，適切適時完成工作。", "富有責任感，認識本身工作職責，完成指派的工作。", "有責任感、貫徹命令與工作努力程度尚可。", "責任感稍差，常不能貫徹指示命令，時有逃避責任之事情。", "無責任感，時常半途而廢，掩飾虛報，不能放心交辦工作。"], "levels": [[9.0, 9.5, 10.0], [7.5, 8.0, 8.5], [6.0, 6.5, 7.0], [4.5, 5.0, 5.5], [3.0, 3.5, 4.0]]}, {"name": "工作效率情形", "sourceName": "工率作情效形", "desc": "指在一定的時間內完成預定工作的量和速度。", "criteria": ["工作效率超群，指派工作均能在預定時間內適切完成，並加覆核。", "工作效率高，能在預定時間內完成工作並加覆核。", "工作效率為一般水準，能在預定時間內完成工作。", "工作效率稍差，有時未能在預定時間內完成工作，須加催促。", "工作效率差，雖加催促亦不能在預定時間內完成工作。"], "levels": [[18.0, 19.0, 20.0], [15.0, 16.0, 17.0], [12.0, 13.0, 14.0], [9.0, 10.0, 11.0], [6.0, 7.0, 8.0]]}, {"name": "工作精確程度", "sourceName": "工確作程精度", "desc": "指工作有無錯誤，是否細心？就工作成果之良好及正確性的程度加以考核。", "criteria": ["工作處理經過與結束極具安定性與正確性，能充分信賴。", "工作細心，成果正確，能信賴。", "偶而會發生錯誤，但工作成果尚稱良好。", "時常發生錯誤，工作成果稍差。", "雖加督導，工作成果仍差，粗心大意，浪費多。"], "levels": [[18.0, 19.0, 20.0], [15.0, 16.0, 17.0], [12.0, 13.0, 14.0], [9.0, 10.0, 11.0], [6.0, 7.0, 8.0]]}];
let rubrics=staffRubrics;
const role=document.querySelector("#role");
const interview=document.querySelector('#interview');
questions.forEach((q,i)=>{const label=document.createElement('label');label.htmlFor='q'+i;label.textContent=q;const area=document.createElement('textarea');area.id='q'+i;interview.append(label,area);fields.push(area.id)});
const scores=document.querySelector('#scores');
function renderScores(){scores.replaceChildren();rubrics.forEach((r,i)=>{const box=document.createElement('div');box.className='rubric';const head=document.createElement('div');head.className='rubric-head';const label=document.createElement('label');label.htmlFor='score'+i;label.textContent=r.name+'｜自評分數';const input=document.createElement('select');input.id='score'+i;const blank=document.createElement('option');blank.value='';blank.textContent='請選擇分數';input.append(blank);[...new Set(r.levels.flat())].sort((a,b)=>a-b).forEach(n=>{const opt=document.createElement('option');opt.value=String(n);opt.textContent=n+' 分';input.append(opt)});const error=document.createElement('span');error.className='score-error';error.id='scoreError'+i;error.hidden=true;head.append(label,error,input);box.append(head);const desc=document.createElement('p');desc.className='rubric-desc';desc.textContent=r.desc;box.append(desc);const table=document.createElement('table');const tr=document.createElement('tr');['優','上','中','下','劣'].forEach(t=>{const th=document.createElement('th');th.textContent=t;tr.append(th)});const row=document.createElement('tr');r.levels.forEach(vals=>{const td=document.createElement('td');td.textContent=vals.join('／');row.append(td)});table.append(tr,row);box.append(table);const criteria=document.createElement('div');r.criteria.forEach((detail,j)=>{const p=document.createElement('p');p.style.cssText='font-size:13px;line-height:1.55;margin:8px 0';const strong=document.createElement('strong');strong.textContent=['優','上','中','下','劣'][j]+'：';p.append(strong,document.createTextNode(detail));criteria.append(p)});box.append(criteria);scores.append(box);});}
let showScoreWarnings=false;function validateScores(){let ok=true;rubrics.forEach((r,i)=>{const el=document.getElementById('score'+i),error=document.getElementById('scoreError'+i);const raw=el.value.trim();const allowed=r.levels.flat();const valid=raw!==''&&allowed.some(n=>n===Number(raw));el.classList.toggle('invalid',showScoreWarnings&&!valid);el.setAttribute('aria-invalid',String(showScoreWarnings&&!valid));error.hidden=valid||!showScoreWarnings;error.textContent=valid?'':raw?'分數異常，請重新選擇':'請選擇自評分數';if(!valid)ok=false});return ok}
document.querySelector('#scores').addEventListener('change',()=>{showScoreWarnings=true;validateScores();recalc();dirty=true});
function total(){return rubrics.reduce((sum,r,i)=>{const raw=document.getElementById('score'+i).value.trim();if(raw==='')return sum;const value=Number(raw);return r.levels.flat().some(n=>n===value)?sum+value:sum},0)}
function recalc(){const t=total();const filled=rubrics.filter((r,i)=>r.levels.flat().includes(Number(document.getElementById('score'+i).value))&&document.getElementById('score'+i).value!=='').length;document.querySelector('#scoreProgress').textContent='已完成 '+filled+'／'+rubrics.length+' 題';document.querySelector('#scoreCompletion').textContent=filled===rubrics.length?'✓ 自評已完成':'自評尚未完成';document.querySelector('#sum').textContent=String(t);const custom=document.querySelector('#override').checked;document.querySelector('#manualBox').hidden=!custom;document.querySelector('#effective').textContent=custom?document.querySelector('#manual').value||'尚未填寫':String(t)}
function snapshot(){const data={};fields.forEach(id=>{const el=document.getElementById(id);if(el)data[id]=el.value});rubrics.forEach((_,i)=>data['score'+i]=document.getElementById('score'+i).value);data.override=document.querySelector('#override').checked;return data}
function restore(data){if(!data||typeof data!=='object')return;fields.forEach(id=>{const el=document.getElementById(id);if(el)el.value=typeof data[id]==='string'?data[id]:''});rubrics.forEach((_,i)=>{const el=document.getElementById('score'+i);el.value=typeof data['score'+i]==='string'?data['score'+i]:''});document.querySelector('#override').checked=data.override===true;validateScores();recalc()}
const keyForRole=()=> 'employee-self-review-demo-v6-'+role.value;
let dirty=false,loading=false;
const status=document.querySelector('#status'),draftInfo=document.querySelector('#draftInfo');
function readDraft(){try{const raw=window.HRGoogleCache.getItem(keyForRole());return raw?JSON.parse(raw):null}catch(e){status.textContent='讀取暫存失敗，請確認瀏覽器是否允許本機儲存';return null}}
function updateDraftInfo(){const saved=readDraft();draftInfo.textContent=saved&&saved.savedAt?'此類別上次暫存：'+new Date(saved.savedAt).toLocaleString('zh-TW')+'（僅限目前瀏覽器）':'此類別尚無暫存草稿'}
function clearForm(){fields.forEach(id=>document.getElementById(id).value='');rubrics.forEach((_,i)=>document.getElementById('score'+i).value='');showScoreWarnings=false;document.querySelectorAll('.required-error').forEach(el=>el.classList.remove('required-error'));document.querySelectorAll('.field-error').forEach(el=>el.hidden=true);document.getElementById('checkStatus').textContent='';document.querySelector('#override').checked=false;recalc()}
function loadDraft(){const saved=readDraft();if(!saved){status.textContent='這個類別目前沒有已儲存的草稿';return}if(dirty&&!confirm('恢復草稿會覆蓋目前尚未暫存的內容，確定嗎？'))return;loading=true;clearForm();restore(saved.data);loading=false;dirty=false;status.textContent='已恢復上次暫存的面談、工作成果與自評分數；簽名請重新操作。'}
function setRole(next){rubrics=next==='supervisor'?supervisorRubrics:staffRubrics;showScoreWarnings=false;renderScores();validateScores();recalc()}
document.querySelectorAll('input,textarea').forEach(el=>el.addEventListener('input',()=>{recalc();if(!loading)dirty=true;el.classList.remove('required-error');const hint=document.getElementById('required-'+el.id);if(hint)hint.hidden=true}));
document.querySelector('#override').addEventListener('change',()=>{recalc();dirty=true});
role.addEventListener('change',()=>{loading=true;clearForm();setRole(role.value);loading=false;dirty=false;updateDraftInfo();status.textContent='已切換考績類別；按「恢復已存草稿」才會載入此類別資料。'});
setRole(role.value);updateDraftInfo();
if(readDraft())status.textContent='偵測到這個類別有暫存草稿，請按「恢復已存草稿」繼續填寫。';
document.querySelector('#resume').addEventListener('click',loadDraft);document.querySelector('#check').addEventListener('click',()=>{let first=null;for(const id of fields.filter(x=>x!=='manual'&&x!=='reason')){const el=document.getElementById(id);if(!el)continue;const missing=!el.value.trim();el.classList.toggle('required-error',missing);let hint=document.getElementById('required-'+id);if(!hint){hint=document.createElement('p');hint.id='required-'+id;hint.className='field-error';el.insertAdjacentElement('afterend',hint)}hint.textContent=missing?'此欄位為必填，請填寫內容':'';hint.hidden=!missing;if(missing&&!first)first=el}showScoreWarnings=true;validateScores();for(let i=0;i<rubrics.length;i++){const el=document.getElementById('score'+i);if(!el.value&&!first)first=el}if(document.querySelector('#override').checked){for(const id of ['manual','reason']){const el=document.getElementById(id);const bad=!el.value.trim()||(id==='manual'&&(+el.value<0||+el.value>100));el.classList.toggle('required-error',bad);if(bad&&!first)first=el}}const msg=document.getElementById('checkStatus');msg.textContent=first?'尚有必填欄位未完成，請查看紅框提示。':'\u586b\u5beb\u5b8c\u6574\uff0c\u53ef\u78ba\u8a8d\u9001\u51fa';if(first)first.focus();});
document.querySelector('#save').addEventListener('click',()=>{try{const record={savedAt:new Date().toISOString(),data:snapshot()};window.HRGoogleCache.setItem(keyForRole(),JSON.stringify(record));dirty=false;updateDraftInfo();status.textContent='✓ 已暫存面談、工作成果及自評分數（不含簽名）。僅存於這台裝置的此瀏覽器。'}catch(e){status.textContent='暫存失敗，請勿關閉頁面。'}});
document.querySelector('#reset').addEventListener('click',()=>{if(!confirm('確定刪除目前類別的本機草稿並清空畫面？此操作無法復原。'))return;try{window.HRGoogleCache.removeItem(keyForRole())}catch(e){}loading=true;clearForm();loading=false;dirty=false;updateDraftInfo();status.textContent='已清除這個類別的本機演練草稿。'});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
recalc();

// HR period state preview only. No real access or submission enforcement.
(()=>{const mode=document.getElementById('previewMode'),target=document.getElementById('previewState');function render(){let data={periodStatus:'draft',start:'2026/11/01',end:'2026/11/30',year:'115'};try{const saved=JSON.parse(window.HRGoogleCache.getItem('hr-review-period-demo-v1'));if(saved&&typeof saved==='object')data={...data,...saved}}catch(e){}const status=mode.value==='saved'?data.periodStatus:mode.value;const start=String(data.start).replaceAll('-','/'),end=String(data.end).replaceAll('-','/');const msgs={draft:'尚未開放 '+data.year+' 年度考績自評。預計開放日：'+start+'。',open:data.year+' 年度考績自評開放填寫中，截止日：'+end+'。',closed:data.year+' 年度考績自評已截止／關閉，無法再填寫。',submitted:'您已完成送出，不能再次查看或修改已送出的自評內容。'};target.textContent=msgs[status]||msgs.draft}mode.addEventListener('change',render);window.addEventListener('focus',render);window.addEventListener('storage',render);document.addEventListener('visibilitychange',()=>{if(!document.hidden)render()});document.getElementById('exitAdmin').addEventListener('click',render);render()})();
function setActive(id){['showEmployees','showAccounts','showReviews','showMultiSite','showAcceptance','showMaintenance'].forEach(x=>document.getElementById(x).classList.toggle('active',x===id))}
// Shared single-site prototype navigation; no security is implied.
(()=>{const open=document.getElementById('openAdmin'),shell=document.getElementById('adminShell'),login=document.getElementById('adminLogin'),demo=document.getElementById('adminDemo'),frame=document.getElementById('adminFrame');open.addEventListener('click',()=>{shell.hidden=false;login.hidden=false;demo.hidden=true;document.body.style.overflow='hidden'});document.getElementById('exitAdmin').addEventListener('click',()=>{shell.hidden=true;document.body.style.overflow='';open.focus()});document.getElementById('enterDemoAdmin').addEventListener('click',()=>{login.hidden=true;demo.hidden=false;if(!frame.getAttribute('src'))frame.src='hr-employee-management.html';setActive('showEmployees')});document.getElementById('showEmployees').addEventListener('click',()=>{frame.src='hr-employee-management.html';frame.title='員工資料管理功能頁面';setActive('showEmployees')});document.getElementById('showAccounts').addEventListener('click',()=>{frame.src='hr-access-management.html';frame.title='帳號與權限管理功能頁面';setActive('showAccounts')});document.getElementById('showReviews').addEventListener('click',()=>{frame.src='hr-review-period.html';frame.title='考績年度與資料查詢功能頁面';setActive('showReviews')});document.getElementById('showMultiSite').addEventListener('click',()=>{frame.src='hr-multi-site-review.html';frame.title='多工地主管評核管理功能頁面';setActive('showMultiSite')});document.getElementById('showMaintenance').addEventListener('click',()=>{frame.src='hr-maintenance-center.html';frame.title='系統維護中心功能頁面';setActive('showMaintenance')});document.getElementById('showAcceptance').addEventListener('click',()=>{frame.src='hr-acceptance-walkthrough.html';frame.title='人事完整流程試行功能頁面';setActive('showAcceptance')});})();
